UPDATE withdrawal
SET status = #{status}
WHERE withdrawal_id = #{withdrawalId}

UPDATE left_amount
SET cur_amount = cur_amount - #{deductAmount}
WHERE left_amount.left_amount_id = #{leftAmountId}
    AND cur_amount >= #{deductAmount}

UPDATE account
SET amount = amount - #{requestedAmount}
WHERE account_id = #{accountId}
AND amount >= #{requestedAmount}
